1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  describe("quoting a premium — price list", () => {
6	    it("quotes a sword: base 100 G + 10 % first-insurance surcharge + 5 G fee = 115 G", () => {
7	      const scenario = {
8	        customer: { yearsWithMHPCO: 0 },
9	        steps: [
10	          {
11	            op: "quote",
12	            items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
13	          },
14	        ],
15	      };
16	
17	      expect(runScenario(scenario)).toEqual({ results: [{ premium: 115 }] });
18	    });
19	    it.todo("quotes an amulet: base 60 G + 10 % + 5 G = 71 G");
20	    it.todo("quotes a staff: base 80 G + 10 % + 5 G = 93 G");
21	    it.todo("quotes a potion: base 40 G + 10 % + 5 G = 49 G");
22	    it.todo("quotes a single rune component: base 25 G + 10 % + 5 G = 33 G");
23	    it.todo("quotes a single moonstone component: base 25 G + 10 % + 5 G = 33 G");
24	    it.todo("sums the base premiums of several main items: sword + potion = 140 G base, + 10 % + 5 G = 159 G");
25	  });
26	
27	  describe("quoting a premium — component building blocks", () => {
28	    it.todo("charges 60 G for a building block of 3 alike components instead of 75 G: + 10 % + 5 G = 71 G");
29	    it.todo("charges 60 G + 25 G for 4 alike components: + 10 % + 5 G = 99 G");
30	    it.todo("charges 120 G for 6 alike components (two building blocks): + 10 % + 5 G = 137 G");
31	    it.todo("does not form a building block from unalike components: 2 runes + 1 moonstone = 75 G base, + 10 % + 5 G = 88 G");
32	  });
33	
34	  describe("quoting a premium — risk surcharges", () => {
35	    it.todo("adds a 50 % risk surcharge for a cursed sword: 150 G, + 10 % + 5 G = 170 G");
36	    it.todo("adds a 30 % risk surcharge for a highly enchanted sword (enchantment 5): 130 G, + 10 % + 5 G = 148 G");
37	    it.todo("does not add the enchantment surcharge below level 5 (enchantment 4): 100 G, + 10 % + 5 G = 115 G");
38	    it.todo("applies both surcharges to a cursed, highly enchanted sword: 100 × 1.5 × 1.3 = 195 G, + 10 % + 5 G = 220 G");
39	    it.todo("applies risk surcharges per item, not to the whole policy: cursed sword + plain potion = 190 G, + 10 % + 5 G = 214 G");
40	  });
41	
42	  describe("quoting a premium — customer modifiers", () => {
43	    it.todo("gives a 20 % loyalty discount to a customer of 2 years: sword 100 × 1.1 × 0.8 = 88 G + 5 G = 93 G");
44	    it.todo("gives no loyalty discount to a customer of 1 year: sword = 115 G");
45	    it.todo("applies the 10 % initial assessment surcharge only to the first contract");
46	    it.todo("gives a 15 % discount on the second contract: sword 100 × 0.85 + 5 G = 90 G");
47	    it.todo("gives the 15 % discount on the third contract as well: sword 100 × 0.85 + 5 G = 90 G");
48	    it.todo("combines loyalty and repeat-contract discounts on a later contract: sword 100 × 0.8 × 0.85 + 5 G = 73 G");
49	    it.todo("adds the 5 G processing fee to every premium, including repeat contracts");
50	  });
51	
52	  describe("quoting a premium — rounding", () => {
53	    it.todo("rounds the premium up, in the MHPCO's favor: amulet for a 5-year customer 60 × 1.1 × 0.8 = 52.8 → 53 G + 5 G = 58 G");
54	  });
55	
56	  describe("processing claims — deductible and reimbursement", () => {
57	    it.todo("subtracts the 100 G deductible from the damage amount: 200 G damage on an amulet pays out 100 G");
58	    it.todo("pays out 0 G when the damage does not exceed the deductible: 100 G damage pays out 0 G");
59	    it.todo("applies the deductible once per damage event, not per damaged item: two 200 G damages in one incident pay out 300 G");
60	    it.todo("reimburses damage to an item with enchantment 8 at 50 %: 500 G damage → 250 G − 100 G deductible = 150 G");
61	    it.todo("reimburses damage to an item with enchantment 7 in full: 500 G damage → 400 G");
62	    it.todo("fully reimburses damage to an item made of dragon material even at enchantment 8: 500 G damage → 400 G");
63	  });
64	
65	  describe("processing claims — payout cap", () => {
66	    it.todo("reports the remaining cap after a claim: amulet insured at 600 G has a 1200 G cap, 200 G damage leaves 1100 G");
67	    it.todo("caps the payout at twice the insurance sum: a single huge claim on an amulet pays at most 1200 G and leaves 0 G");
68	    it.todo("caps the cumulative payout across several claims on the same policy");
69	    it.todo("pays out 0 G once the cap is exhausted");
70	    it.todo("bases the cap on the summed insurance value of all insured items: sword + amulet = 1600 G insured → 3200 G cap");
71	    it.todo("tracks caps of several policies independently");
72	  });
73	
74	  describe("scenario processing", () => {
75	    it.todo("returns an empty results array for a scenario without steps");
76	    it.todo("returns one result per step, in order, matching the schema example 1 shape");
77	    it.todo("processes a quote followed by two claims against it, as in schema example 2");
78	  });
79	});
